import type { FC } from "react";

interface ButtonProps {
  label: string;
  onClick: () => void;
}

const Button: FC<ButtonProps> = ({ label, onClick }) => (
  <button onClick={onClick}>{label}</button>
);

export function CalculatorWidget(): JSX.Element {
  const [display, setDisplay] = React.useState<string>("");

  const handleClick = (value: string): void => {
    setDisplay(prevDisplay => prevDisplay + value);
  };

  const handleClear = (): void => {
    setDisplay("");
  };

  const handleEvaluate = (): void => {
    try {
      setDisplay(eval(display).toString());
    } catch (e) {
      setDisplay("Error");
    }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <input
        type="text"
        value={display}
        readOnly
        style={{ width: "100px", padding: "10px", fontSize: "24px" }}
      />
      <div style={{ display: "grid", gridTemplateRows: "repeat(4, 1fr)", gap: "5px" }}>
        <Button label="7" onClick={() => handleClick("7")} />
        <Button label="8" onClick={() => handleClick("8")} />
        <Button label="9" onClick={() => handleClick("9")} />
        <Button label="/" onClick={() => handleClick("/")} />
        <Button label="4" onClick={() => handleClick("4")} />
        <Button label="5" onClick={() => handleClick("5")} />
        <Button label="6" onClick={() => handleClick("6")} />
        <Button label="*" onClick={() => handleClick("*")} />
        <Button label="1" onClick={() => handleClick("1")} />
        <Button label="2" onClick={() => handleClick("2")} />
        <Button label="3" onClick={() => handleClick("3")} />
        <Button label="+" onClick={() => handleClick("+")} />
        <Button label="C" onClick={handleClear} />
        <Button label="0" onClick={() => handleClick("0")} />
        <Button label="." onClick={() => handleClick(".")} />
        <Button label="=" onClick={handleEvaluate} />
      </div>
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export interface Product {
  id: number;
  name: string;
  price: number;
  stockCount: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    price REAL NOT NULL,
    stockCount INTEGER NOT NULL
  );
`);

export function insertProduct(name: string, price: number, stockCount: number): void {
  db.prepare(`INSERT INTO products (name, price, stockCount) VALUES (?, ?, ?)`).run(name, price, stockCount);
}

export function getProductById(id: number): Product | undefined {
  const stmt = db.prepare(`SELECT * FROM products WHERE id = ?`).get(id);
  return stmt as unknown as Product;
}

export function getAllProducts(): Product[] {
  const stmt = db.prepare(`SELECT * FROM products`).all();
  return stmt as unknown as Product[];
}

export function updateProductStock(id: number, stockCount: number): void {
  db.prepare(`UPDATE products SET stockCount = ? WHERE id = ?`).run(stockCount, id);
}

