interface ApplicationFormData {
  resumeFile: File | null;
  coverNote: string;
}

export function ApplicationForm(): JSX.Element {
  const [formData, setFormData] = useState<ApplicationFormData>({ resumeFile: null, coverNote: "" });

  const handleResumeChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    if (event.target.files && event.target.files.length > 0) {
      setFormData({ ...formData, resumeFile: event.target.files[0] });
    }
  };

  const handleCoverNoteChange = (event: React.ChangeEvent<HTMLTextAreaElement>): void => {
    setFormData({ ...formData, coverNote: event.target.value });
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault();

    if (!formData.resumeFile || formData.coverNote.trim() === "") {
      alert("Please upload a resume and enter a cover note.");
      return;
    }

    const formDataObject = new FormData();
    formDataObject.append("resume", formData.resumeFile);
    formDataObject.append("coverNote", formData.coverNote);

    try {
      const response = await fetch("/api/applications-api/postings/:postingId/applications", {
        method: "POST",
        body: formDataObject,
      });

