interface Book {
  id: number;
  title: string;
  author: string;
  copies: number;
}

export function StaffInventoryPanel(): JSX.Element {
  const [books, setBooks] = useState<Book[]>([]);

  useEffect(() => {
    fetch("/api/catalogue-api/books")
      .then(response => response.json())
      .then(data => setBooks(data));
  }, []);

  const handleAddBook = async (title: string, author: string, copies: number) => {
    const newBook = { title, author, copies };
    const response = await fetch("/api/catalogue-api/books", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newBook),
    });
    if (response.ok) {
      setBooks([...books, newBook]);
    }
  };

  const handleUpdateCopies = async (id: number, copies: number) => {
    const updatedBook = { id, copies };
    const response = await fetch(`/api/catalogue-api/books/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updatedBook),
    });
    if (response.ok) {
      setBooks(books.map(book => (book.id === id ? { ...book, copies } : book)));
    }
  };

  const handleDeleteBook = async (id: number) => {
    const response = await fetch(`/api/catalogue-api/books/${id}`, {
      method: "DELETE",
    });
    if (response.ok) {
      setBooks(books.filter(book => book.id !== id));
    }
  };

  return (
    <div>
      <h1>Staff Inventory Panel</h1>
      <button onClick={() => handleAddBook("New Book", "Author", 1)}>Add Book</button>
      <ul>
        {books.map(book => (
          <li key={book.id}>
            {book.title} by {book.author} - Copies: {book.copies}
            <button onClick={() => handleUpdateCopies(book.id, book.copies + 1)}>Add Copy</button>
            <button onClick={() => handleUpdateCopies(book.id, book.copies - 1)}>Remove Copy</button>
            <button onClick={() => handleDeleteBook(book.id)}>Delete Book</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

