interface ExpenseFormData {
  amount: number;
  category: string;
  receiptFile?: File;
}

export function ExpenseSubmissionForm(): JSX.Element {
  const [formData, setFormData] = useState<ExpenseFormData>({ amount: 0, category: "" });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>): void => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: name === "amount" ? Number(value) : value });
  };

  const handleReceiptChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    const file = e.target.files?.[0];
    if (file) {
      setFormData({ ...formData, receiptFile: file });
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    const formDataObj = new FormData();
    formDataObj.append("amount", String(formData.amount));
    formDataObj.append("category", formData.category);
    if (formData.receiptFile) {
      formDataObj.append("receipt", formData.receiptFile);
    }

    try {
      const response = await fetch("/api/expenses-api/", {
        method: "POST",
        body: formDataObj,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      console.log("Expense submitted successfully");
    } catch (error) {
      console.error("Error submitting expense:", error);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="amount">Amount:</label>
        <input
          type="number"
          id="amount"
          name="amount"
          value={formData.amount}
          onChange={handleInputChange}
          required
        />
      </div>
      <div>
        <label htmlFor="category">Category:</label>
        <input
          type="text"
          id="category"
          name="category"
          value={formData.category}
          onChange={handleInputChange}
          required
        />
      </div>
      <div>
        <label htmlFor="receipt">Receipt:</label>
        <input
          type="file"
          id="receipt"
          name="receipt"
          onChange={handleReceiptChange}
        />
      </div>
      <button type="submit">Submit Expense</button>
    </form>
  );
}

