import { DatabaseSync } from "node:sqlite";

export interface Shift {
  id: number;
  description: string;
  startTime: string;
  endTime: string;
  capacity: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    description TEXT NOT NULL,
    startTime TEXT NOT NULL,
    endTime TEXT NOT NULL,
    capacity INTEGER NOT NULL
  );
`);

export function createShift(description: string, startTime: string, endTime: string, capacity: number): void {
  db.prepare(`INSERT INTO shifts (description, startTime, endTime, capacity) VALUES (?, ?, ?, ?)`).run(description, startTime, endTime, capacity);
}

export function getShiftById(id: number): Shift | undefined {
  const stmt = db.prepare(`SELECT * FROM shifts WHERE id = ?`).get(id);
  return stmt as unknown as Shift;
}

export function getAllShifts(): Shift[] {
  const stmt = db.prepare(`SELECT * FROM shifts`).all();
  return stmt as unknown as Shift[];
}

export function updateShift(id: number, description: string, startTime: string, endTime: string, capacity: number): void {
  db.prepare(`UPDATE shifts SET description = ?, startTime = ?, endTime = ?, capacity = ? WHERE id = ?`).run(description, startTime, endTime, capacity, id);
}

export function deleteShift(id: number): void {
  db.prepare(`DELETE FROM shifts WHERE id = ?`).run(id);
}

