  timestamp: number;
}

export const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE IF NOT EXISTS clock_events (
    employeeId INTEGER,
    eventType TEXT CHECK(eventType IN ('in', 'out')),
    timestamp INTEGER
  );
`);

export function insertClockEvent(employeeId: number, eventType: 'in' | 'out', timestamp: number): void {
  db.prepare('INSERT INTO clock_events (employeeId, eventType, timestamp) VALUES (?, ?, ?)').run(employeeId, eventType, timestamp);
