import React, { FC, useState } from "react";

interface ShiftEvent {
  type: "clockIn" | "clockOut";
  timestamp: number;
}

export function ClockInOutWidget(): JSX.Element {
  const [event, setEvent] = useState<ShiftEvent | null>(null);

  const handleClockIn = async () => {
    const now = Date.now();
    setEvent({ type: "clockIn", timestamp: now });
    await fetch("/api/timesheets-api/events", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ type: "clockIn", timestamp: now }),
    });
  };

  const handleClockOut = async () => {
    const now = Date.now();
    setEvent({ type: "clockOut", timestamp: now });
    await fetch("/api/timesheets-api/events", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ type: "clockOut", timestamp: now }),
    });
  };

  return (
    <div>
      <button onClick={handleClockIn}>Clock In</button>
      <button onClick={handleClockOut}>Clock Out</button>
      {event && <p>Last event: {event.type} at {new Date(event.timestamp).toLocaleTimeString()}</p>}
    </div>
  );
}

