import React, { FC, useState, useEffect } from "react";

interface Spot {
  id: number;
  status: string;
}

export function SpotReservationView(): JSX.Element {
  const [spots, setSpots] = useState<Spot[]>([]);

  useEffect(() => {
    fetch("/api/parking-api/reservations")
      .then(response => response.json())
      .then(data => setSpots(data));
  }, []);

  const handleReserveClick = (spotId: number) => {
    fetch(`/api/parking-api/reservations/${spotId}/${new Date().toISOString().split('T')[0]}`, { method: "POST" })
      .then(response => response.json())
      .then(updatedSpots => setSpots(updatedSpots));
  };

  return (
    <div>
      <h1>Today's Parking Spots</h1>
      <ul>
        {spots.map(spot => (
          <li key={spot.id} style={{ color: spot.status === "reserved" ? "red" : "green" }}>
            Spot {spot.id}: {spot.status}
            {spot.status !== "reserved" && <button onClick={() => handleReserveClick(spot.id)}>Reserve</button>}
          </li>
        ))}
      </ul>
    </div>
  );
}
